@Around("@within(com.mongoplus.annotation.datasource.MongoDs) || @annotation(com.mongoplus.annotation.datasource.MongoDs)")
public Object manageDataSource(ProceedingJoinPoint joinPoint) throws Throwable {
    MethodSignature methodSignature = (MethodSignature) joinPoint.getSignature();
    Method method = methodSignature.getMethod();

    // 获取方法或类上的注解
    MongoDs mongoDs = getMongoDsAnnotation(method);
    String mongoDsValue = mongoDs.value();
    if (StringUtils.isNotBlank(mongoDsValue) && mongoDsValue.contains("#")) {
        StandardEvaluationContext context =
                new MethodBasedEvaluationContext(joinPoint, method, joinPoint.getArgs(), PARAMETER_NAME_DISCOVERER);
        mongoDsValue = EXPRESSION_PARSER
                .parseExpression(mongoDsValue.replace("#",""))
                .getValue(context, String.class);
    }

    if (mongoDs.dsHandler() != Void.class){
        DataSourceHandler dataSourceHandler =
                (DataSourceHandler) ClassTypeUtil.getInstanceByClass(mongoDs.dsHandler());
        mongoDsValue = dataSourceHandler.getDataSource(mongoDsValue);
    }

    if (StringUtils.isBlank(mongoDsValue)) {
        throw new MongoPlusException("Data source not found");
    }

    DataSourceNameCache.setDataSource(mongoDsValue);

    try {
        return joinPoint.proceed();
    } finally {
        DataSourceNameCache.clear();
    }
}

@Override
public void postProcessEnvironment(ConfigurableEnvironment environment, SpringApplication application) {
    String secretKey = environment.getProperty("mpw.key");

    // 如果 secretKey 为空，直接返回
    if (StringUtils.isBlank(secretKey)) {
        return;
    }

    environment.getPropertySources().stream()
            .filter(OriginTrackedMapPropertySource.class::isInstance)
            .forEach(propertySource -> {
                String sourceName = propertySource.getName();
                PropertySource<Object> encryptedPropertySource = new PropertySource<Object>(sourceName) {
                    @Override
                    @SuppressWarnings("NullableProblems")
                    public Object getProperty(String name) {
                        Object property = propertySource.getProperty(name);
                        if (property != null) {
                            String value = property.toString();
                            if (detected(value)) {
                                try {
                                    return AESExample.decrypt(unWrapper(value), secretKey);
                                } catch (Exception e) {
                                    throw new MongoPlusEncryptException("Configuration decryption failed", e);
                                }
                            }
                        }
                        return property;
                    }
                };
                environment.getPropertySources().replace(sourceName, encryptedPropertySource);
            });
}

public boolean detected(String property) {
    return property != null && property.startsWith(PREFIX) && property.endsWith(SUFFIX);
}

public class MongoMapperScannerRegistrar implements ImportBeanDefinitionRegistrar {

    @Override
    public void registerBeanDefinitions(AnnotationMetadata metadata, @NonNull BeanDefinitionRegistry registry) {
        Map<String, Object> attributes = metadata.getAnnotationAttributes(MongoMapperScan.class.getName());
        String[] basePackages = null;
        if (attributes != null) {
            basePackages = (String[]) attributes.get("value");
        }

        if (basePackages != null) {
            for (String basePackage : basePackages) {
                ClassPathMongoMapperScanner scanner = new ClassPathMongoMapperScanner(registry);
                scanner.addIncludeFilter(new MongoMapperTypeFilter());
                scanner.scan(basePackage);
            }
        }
    }

    /**
     * MongoMapper接口的扫描过滤器，如果实现的接口不是MongoMapper，则返回false,
     * AssignableTypeFilter类默认返回null，实现的接口不是MongoMapper也会扫描到
     * @author anwen
     */
    public static class MongoMapperTypeFilter extends AssignableTypeFilter {

        public MongoMapperTypeFilter() {
            super(MongoMapper.class);
        }

        @Override
        protected Boolean matchTargetType(@NonNull String typeName) {
            Boolean _b = super.matchTargetType(typeName);
            return _b != null && _b;
        }
    }

}

