@Override
public Object read(FieldInformation fieldInformation, Object source) {
    Desensitization desensitization = fieldInformation.getAnnotation(Desensitization.class);
    if (fieldInformation.isAnnotation(Desensitization.class)){
        Class<?> desensitizationClass = desensitization.desensitizationHandler();
        if (desensitizationClass != Void.class && ClassTypeUtil.isTargetClass(DesensitizationHandler.class,desensitizationClass)){
            DesensitizationHandler desensitizationHandler = (DesensitizationHandler) ClassTypeUtil.getInstanceByClass(desensitizationClass);
            source = desensitizationHandler.desensitized(fieldInformation.getField(),
                    source, desensitization.startInclude(), desensitization.endExclude(), desensitization.type());
        } else {
            String desensitizationValue;
            try {
                desensitizationValue = String.valueOf(source);
            } catch (Exception e) {
                throw new MongoPlusConvertException("Fields that require desensitization cannot be converted to strings");
            }
            source = DesensitizedUtil.desensitized(desensitizationValue, desensitization.startInclude(), desensitization.endExclude(), desensitization.type());
        }
    }
    return source;
}

@Override
public Object read(FieldInformation fieldInformation, Object source) {
    FieldBind fieldBind = fieldInformation.getAnnotation(FieldBind.class);
    String target = StringUtils.camelToUnderline(fieldBind.target());
    TypeInformation typeInformation = TypeInformation.of(fieldInformation.getInstance());
    FieldInformation targetFieldInformation = typeInformation.getField(target);
    if (targetFieldInformation == null) {
        throw new MongoPlusFieldException("fieldBind target field not found");
    }
    dataBindHandler.setMetaObject(fieldInformation.getAnnotation(FieldBind.class), source, targetFieldInformation);
    return source;
}

@Override
public Object read(FieldInformation fieldInformation, Object source) {
    FieldEncrypt fieldEncrypt = fieldInformation.getAnnotation(FieldEncrypt.class);
    if (fieldEncrypt != null && fieldEncrypt.findDecrypt()){
        source = EncryptorUtil.decrypt(fieldInformation.getAnnotation(FieldEncrypt.class),source);
    }
    return source;
}

@Override
public Serializable generateId(IdTypeEnum idTypeEnum, TypeInformation typeInformation) {
    if (idTypeEnum.getKey() == IdTypeEnum.ASSIGN_UUID.getKey()){
        return IdWorker.get32UUID();
    }
    if (idTypeEnum.getKey() == IdTypeEnum.ASSIGN_ULID.getKey()){
        return IdWorker.get26ULID();
    }
    if (idTypeEnum.getKey() == IdTypeEnum.ASSIGN_ID.getKey()){
        return IdWorker.getId();
    }
    if (idTypeEnum.getKey() == IdTypeEnum.AUTO.getKey()){
        return generateAutoId(typeInformation);
    }
    if (idTypeEnum.getKey() == IdTypeEnum.OBJECT_ID.getKey()){
        return new ObjectId();
    }
    return null;
}

