protected MutablePair<String, String> getNamespace(Class<?> clazz) {

    String database = mongoPlusClient.getDatabase(clazz);
    String collectionName = mongoPlusClient.getCollectionName(clazz);

    // 发布感知事件
    NamespaceAware.Namespace namespace = NamespaceAware.NamespaceBuild.builder()
            .dataBase(database).collectionName(collectionName).entityClass(clazz)
            .build();
    List<NamespaceAware> handlers = MongoAwareUtils.listHandlers(NamespaceAware.class);
    for (NamespaceAware aware : handlers) {
        aware.nameSpaceAware(namespace);
    }

    return new MutablePair<>(database, collectionName);

}

@Override
public Object intercept(Invocation invocation) throws Throwable {
    ExecuteMethodEnum executeMethod = invocation.getExecuteMethod();
    Object[] source = invocation.getArgs();
    MongoCollection<Document> collection = invocation.getCollection();
    if (executeMethod == ExecuteMethodEnum.SAVE) {
        executeSave((List<Document>) source[0], (InsertManyOptions) source[1], collection);
    }
    if (executeMethod == ExecuteMethodEnum.SAVE_ONE) {
        executeSave((Document) source[0], (InsertOneOptions) source[1], collection);
    }
    if (executeMethod == ExecuteMethodEnum.REMOVE || executeMethod == ExecuteMethodEnum.REMOVE_ONE) {
        executeRemove((Bson) source[0], (DeleteOptions) source[1],invocation, collection);
    }
    if (executeMethod == ExecuteMethodEnum.UPDATE) {
        executeUpdate((List<MutablePair<Bson, Bson>>) source[0], (UpdateOptions) source[1], collection);
    }
    if (executeMethod == ExecuteMethodEnum.UPDATE_ONE) {
        executeUpdate((MutablePair<Bson, Bson>) source[0], (UpdateOptions) source[1], collection);
    }
    if (executeMethod == ExecuteMethodEnum.BULK_WRITE) {
        executeBulkWrite((List<WriteModel<Document>>) source[0],(BulkWriteOptions) source[1], collection);
    }
    return invocation.proceed();
}

void executeMultipleWrite(MultipleWrite multipleWrite,MongoCollection<Document> collection,
                                  Consumer<MongoCollection<Document>> action) {
    MongoNamespace namespace = collection.getNamespace();
    List<String> multipleWriteTargets = multipleWriteHandler.getMultipleWrite(multipleWrite, namespace);
    multipleWriteTargets.forEach(dsName -> executor.submit(() -> {
        if (!dsName.equals(DataSourceNameCache.getDataSource())) {
            MongoCollection<Document> mongoCollection = getMongoCollection(namespace, dsName);
            log.info("Executing multiple write operation on data source: " + dsName);
            action.accept(mongoCollection);
        }
    }));
}

public class CollectionLogiceInterceptor implements Interceptor {

    @Override
    public Bson executeRemove(Bson filter, MongoCollection<Document> collection) {
        return remove(filter, collection);
    }

    @Override
    public Bson executeRemoveOne(Bson filter, MongoCollection<Document> collection) {
        return remove(filter, collection);
    }

    Bson remove(Bson filter, MongoCollection<Document> collection) {
        if (LogicManager.isIgnoreLogic()) {
            return filter;
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return filter;
        }
        return LogicDeleteHandler.doBsonLogicDel(filter, clazz);
    }

    @Override
    public QueryParam executeQuery(Bson queryBasic, BasicDBObject projectionList, BasicDBObject sortCond,
                                   MongoCollection<Document> collection) {

        if (LogicManager.isIgnoreLogic()) {
            return new QueryParam(queryBasic, projectionList, sortCond);
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return new QueryParam(queryBasic, projectionList, sortCond);
        }
        Bson query = LogicDeleteHandler.doBsonLogicDel(queryBasic, clazz);
        return new QueryParam(query, projectionList, sortCond);

    }

    @Override
    public MutablePair<BasicDBObject, CountOptions> executeCount(BasicDBObject queryBasic, CountOptions countOptions,
                                                                 MongoCollection<Document> collection) {

        if (LogicManager.isIgnoreLogic()) {
            return new MutablePair<>(queryBasic, countOptions);
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return new MutablePair<>(queryBasic, countOptions);
        }
        BasicDBObject query = (BasicDBObject) LogicDeleteHandler.doBsonLogicDel(queryBasic, clazz);
        return new MutablePair<>(query, countOptions);

    }

    @Override
    @SuppressWarnings("all")
    public List<WriteModel<Document>> executeBulkWrite(List<WriteModel<Document>> writeModelList,
                                                       MongoCollection<Document> collection) {

        if (LogicManager.isIgnoreLogic()) {
            return writeModelList;
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return writeModelList;
        }
        return writeModelList.stream().map(item -> {
            if (item instanceof UpdateManyModel) {
                UpdateManyModel umm = (UpdateManyModel) item;
                Bson filter = LogicDeleteHandler.doBsonLogicDel(umm.getFilter(), clazz);
                WriteModel<Document> updateManyModel = Optional.ofNullable(umm.getOptions())
                        .map(u -> new UpdateManyModel(filter, umm.getUpdate(), u))
                        .orElseGet(() -> new UpdateManyModel(filter, umm.getUpdate()));
                return updateManyModel;
            }
            return item;
        }).collect(Collectors.toList());

    }

    @Override
    public List<Bson> executeAggregates(List<Bson> aggregateConditionList, MongoCollection<Document> collection) {
        if (LogicManager.isIgnoreLogic()) {
            return aggregateConditionList;
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return aggregateConditionList;
        }
        LogicDeleteResult result = LogicDeleteHandler.getLogicDeletedResult(clazz);
        if (Objects.isNull(result)) {
            return aggregateConditionList;
        }
        boolean hasMatch = aggregateConditionList.stream()
                .anyMatch(bson -> BsonUtil.asBsonDocument(bson)
                        .containsKey(AggregateEnum.MATCH.getValue()));
        if (hasMatch) {
            aggregateConditionList = aggregateConditionList.stream()
                    .map(bson -> {
                        BsonDocument bsonDocument = bson.toBsonDocument(BsonDocument.class,
                                MapCodecCache.getDefaultCodecRegistry());
                        if (bsonDocument.containsKey(AggregateEnum.MATCH.getValue())) {
                            BsonDocument matchBsonDocument = bsonDocument.get(AggregateEnum.MATCH.getValue())
                                    .asDocument();
                            matchBsonDocument.putIfAbsent(
                                    result.getColumn(),
                                    new BsonDocument(EQ.getOperatorValue(),
                                            result.getLogicNotDeleteBsonValue())
                            );
                            return bsonDocument;
                        }
                        return bson;
                    })
                    .collect(Collectors.toList());
        } else {
            QueryWrapper<Object> queryWrapper = new QueryWrapper<>();
            queryWrapper.eq(result.getColumn(), result.getLogicNotDeleteValue());
            Bson matchBson = new AggregateWrapper().match(queryWrapper)
                    .getAggregateConditionList().get(0);
            aggregateConditionList.add(matchBson);
        }
        return aggregateConditionList;
    }

    @Override
    public MutablePair<Bson, Bson> executeUpdate(MutablePair<Bson, Bson> updatePair, MongoCollection<Document> collection) {
        if (LogicManager.isIgnoreLogic()) {
            return updatePair;
        }
        Class<?> clazz = LogicDeleteHandler.getBeanClass(collection);
        if (LogicDeleteHandler.close() || Objects.isNull(clazz)) {
            return updatePair;
        }
        Bson filter = LogicDeleteHandler.doBsonLogicDel(updatePair.getLeft(), clazz);
        updatePair.setLeft(filter);
        return updatePair;
    }

    @Override
    public List<MutablePair<Bson, Bson>> executeUpdate(List<MutablePair<Bson, Bson>> updatePairList, MongoCollection<Document> collection) {
        updatePairList.forEach(pair -> {
            executeUpdate(pair, collection);
        });
        return updatePairList;
    }
}

@Override
public void beforeExecute(ExecuteMethodEnum executeMethodEnum, Object[] source,
                          MongoCollection<Document> collection) {
    if (shouldIgnoreCollection(collection)) {
        return;
    }

    long startTs = System.currentTimeMillis();
    OperationResult operationResult = processOperation(executeMethodEnum, source);

    if (operationResult != null) {
        MongoNamespace namespace = collection.getNamespace();
        operationResult.setDatasourceName(DataSourceNameCache.getDataSource());
        operationResult.setDatabaseName(namespace.getDatabaseName());
        operationResult.setCollectionName(namespace.getCollectionName());
        operationResult.setRecordStatus(true);
        long costThis = System.currentTimeMillis() - startTs;
        operationResult.setCost(costThis);
        log.info(String.format("%s DataChangeRecord: %s",executeMethodEnum.name(), operationResult));
        if (enableSaveDatabase) {
            operationResultThreadLocal.set(operationResult);
        }
    }
}

@Override
public void afterExecute(ExecuteMethodEnum executeMethodEnum, Object[] source, Object result,
                         MongoCollection<Document> collection) {
    if (shouldIgnoreCollection(collection) || !isRelevantMethod(executeMethodEnum)) {
        return;
    }

    if (enableSaveDatabase) {
        String previousDatasource = DataSourceNameCache.getDataSourceOrNull();
        try {
            String datasource = determineDatasource();
            DataSourceNameCache.setDataSource(datasource);
            String databaseName = determineDatabaseName();
            baseMapper.save(databaseName, collectionName, operationResultThreadLocal.get());
        } finally {
            operationResultThreadLocal.remove();
            if (previousDatasource == null) {
                DataSourceNameCache.clear();
            } else {
                DataSourceNameCache.setDataSource(previousDatasource);
            }
        }
    }
}

private OperationResult processUpdate(Object[] source) throws DataUpdateLimitationException {
    List<MutablePair<Bson, Bson>> documentList = castList(source[0]);
    if (documentList.size() > batchUpdateLimit) {
        log.error("batch update limit exceed: count={}, BATCH_UPDATE_LIMIT={}", documentList.size(), batchUpdateLimit);
        throw new DataUpdateLimitationException(exceptionMessage);
    }
    OperationResult operationResult = new OperationResult();
    operationResult.setOperation(ExecuteMethodEnum.UPDATE.name());
    List<String> dataList = documentList.stream()
            .map(mutablePair -> {
                String left = mutablePair.getLeft().toBsonDocument(BsonDocument.class, MapCodecCache.getDefaultCodecRegistry()).toString();
                String right = mutablePair.getRight().toBsonDocument(BsonDocument.class, MapCodecCache.getDefaultCodecRegistry()).toString();
                return "(left=" + left + ",right=" + right + ")";
            })
            .collect(Collectors.toList());
    operationResult.setChangedData(displayCompleteData ? dataList.toString() : String.valueOf(documentList.size()));
    return operationResult;
}

