@Override
public void writeBySave(Object sourceObj, Document document) {
    // Map类型不需要再做下边的操作 因为它们只针对实体类
    if (ClassTypeUtil.isTargetClass(Map.class, sourceObj.getClass())) {
        write((Map<?, ?>) sourceObj, document);
        return;
    }
    //封装class信息
    TypeInformation typeInformation = TypeInformation.of(sourceObj);
    //拿到类中的@ID字段
    FieldInformation idFieldInformation = typeInformation.getAnnotationField(ID.class);
    if (idFieldInformation != null) {
        // 获取id值
        Object idValue = idFieldInformation.getValue();
        // 如果自定设置了id
        if (idValue != null) {
            // 如果自设置的值是ObjectId，并且传入的值不是ObjectId类型，则创建并写入
            if (ObjectId.isValid(String.valueOf(idValue)) && !idValue.getClass().equals(ObjectId.class)) {
                idValue = new ObjectId(String.valueOf(idValue));
            }
        } else {
            // 没有自行设置id，则自动生成id
            idValue = HandlerCache.idGenerateHandler.generateId(idFieldInformation.getId().type(), typeInformation);
            // 没有生成id抛出异常
            if (idValue == null) {
                throw new MongoPlusWriteException("The _id cannot be empty, please check the IdGenerateHandler or manually assign it");
            }
            // 如果值不是ObjectId
            if (!(idValue instanceof ObjectId)) {
                // 如果开启了objectId转换类型，并且传入的值是ObjectId格式，则转换为ObjectId类型
                if (PropertyCache.objectIdConvertType && ObjectId.isValid(String.valueOf(idValue))) {
                    idValue = new ObjectId(String.valueOf(idValue));
                } else {
                    // 为满足ObjectId条件，转换为实体类字段类型
                    idValue = convertValue(idValue, idFieldInformation.getTypeClass());
                }
            }
        }
        document.put(SqlOperationConstant._ID, idValue);
        //为自行设置id，需要在这里判断一下重入，自行设置checkTableField方法会进行处理
        if (idFieldInformation.getId().saveField()) {
            document.put(idFieldInformation.getName(), idValue);
        }
    }
    //映射到Document
    write(sourceObj, document);
    //添加自动填充字段
    autoFillHandler.handle(document,typeInformation,FieldFill.INSERT, this);
}

@Override
public void writeByUpdate(Object sourceObj, Document document) {
    // Map类型不需要再做下边的操作 因为它们只针对实体类
    if (ClassTypeUtil.isTargetClass(Map.class, sourceObj.getClass())) {
        write((Map<?, ?>) sourceObj, document);
        return;
    }
    //封装class信息
    TypeInformation typeInformation = TypeInformation.of(sourceObj);
    //拿到类中的@ID字段
    FieldInformation idFieldInformation = typeInformation.getAnnotationField(ID.class, "@ID field not found");
    if (idFieldInformation.getValue() != null) {
        document.put(SqlOperationConstant._ID, idFieldInformation.getValue());
    }
    //映射到Document
    write(sourceObj, document);
    //添加自动填充字段
    autoFillHandler.handle(document,typeInformation,FieldFill.UPDATE, this);
}

@Override
@SuppressWarnings({"unchecked", "rawtypes"})
public <T> T readInternal(Document document, TypeReference<T> typeReference, boolean useIdAsFieldName) {
    Class<?> clazz = typeReference.getClazz();
    if (document == null) {
        return null;
    }
    if (ClassTypeUtil.isTargetClass(Document.class, clazz)) {
        return (T) document;
    } else if (ClassTypeUtil.isTargetClass(Map.class, clazz)) {
        return (T) readInternal(document, new TypeReference<Map<String, Object>>() {
        });
    } else if (ClassTypeUtil.isTargetClass(Collection.class, clazz)) {
        return (T) readInternal(document, new TypeReference<Collection<Object>>() {
        });
    }
    // 拿到class封装类
    TypeInformation typeInformation = TypeInformation.of(clazz);
    // 获取@ExtraFields字段
    FieldInformation extraFieldInformation = typeInformation.getAnnotationField(ExtraFields.class);
    List<String> usedFields;
    if (extraFieldInformation != null) {
        if (!extraFieldInformation.isMap()) {
            throw new MongoPlusConvertException("@ExtraFields can only be used for Map fields");
        }
        usedFields = new ArrayList<>();
    } else {
        usedFields = null;
    }
    // 循环所有字段
    typeInformation.getFields().forEach(fieldInformation -> {
        String fieldName = useIdAsFieldName ? fieldInformation.getIdOrCamelCaseName() : fieldInformation.getCamelCaseName();
        if (fieldInformation.isSkipCheckField()) {
            return;
        }
        Object obj = document.get(fieldName);
        if (obj == null) {
            return;
        }
        if (extraFieldInformation != null) {
            usedFields.add(fieldName);
        }
        CollectionField collectionField = fieldInformation.getCollectionField();
        Object resultObj = null;
        if (collectionField != null && ClassTypeUtil.isTargetClass(TypeHandler.class, collectionField.typeHandler())) {
            TypeHandler typeHandler = (TypeHandler) ClassTypeUtil.getInstanceByClass(collectionField.typeHandler());
            resultObj = typeHandler.getResult(obj);
        }
        if (CollUtil.isNotEmpty(HandlerCache.getReadHandler())) {
            List<ReadHandler> readHandlerList = HandlerCache.getReadHandler();
            for (ReadHandler readHandler : readHandlerList) {
                if (readHandler.activate().apply(fieldInformation)) {
                    obj = readHandler.read(fieldInformation, obj,this);
                }
                if (readHandler.discontinue().apply(obj)) {
                    return;
                }
            }
        }
        if (resultObj == null) {
            resultObj = readInternal(obj, TypeReference.of(fieldInformation.getGenericType()));
        }
        fieldInformation.setValue(resultObj);
    });
    if (extraFieldInformation != null) {

        ExtraFields extraFields = extraFieldInformation.getAnnotation(ExtraFields.class);

        Map extraFieldMap = createExtraMap(extraFields, extraFieldInformation);

        if (ArrayUtils.isNotEmpty(extraFields.ignoredFields())) {
            usedFields.addAll(Arrays.asList(extraFields.ignoredFields()));
        }
        boolean isExtraFieldsHolder = extraFieldInformation.getTypeClass() == ExtraFieldsHolder.class;
        document.keySet().stream()
                .filter(k -> !usedFields.contains(k))
                .forEach(k -> {
                    Object value = document.get(k);
                    if (extraFields.underlineToCamel()) {
                        k = StringUtils.underlineToCamel(k);
                    }
                    if (isExtraFieldsHolder) {
                        ((ExtraFieldsHolder) extraFieldMap).putValue(k, value);
                    } else {
                        extraFieldMap.put(k, value);
                    }
                });

        extraFieldInformation.setValue(extraFieldMap);
    }

    return typeInformation.getInstance();
}

@SuppressWarnings("unchecked")
private Map<String, Object> createExtraMap(ExtraFields extraFields,
                                           FieldInformation extraFieldInformation) {

    Class<?> mapType = extraFields.mapType();

    // 注解指定了 mapType，且不是 LinkedHashMap.class
    if (mapType != LinkedHashMap.class) {
        if (mapType.isInterface()) {
            throw new MongoPlusFieldException("'mapType' should be a class, not an interface");
        }
        return (Map<String, Object>) ClassTypeUtil.getInstanceByClass(mapType);
    }

    Class<?> typeClass = extraFieldInformation.getTypeClass();

    // 如果字段类型是接口，则默认使用 LinkedHashMap
    if (typeClass.isInterface()) {
        return new LinkedHashMap<>();
    }

    // 否则直接实例化字段类型
    return (Map<String, Object>) ClassTypeUtil.getInstanceByClass(typeClass);
}

private void processFields(List<FieldInformation> fields, Bson bson, boolean filterId) {
    fields.stream()
            .filter(fieldInformation -> !fieldInformation.isSkipCheckField() && (!filterId || !fieldInformation.isId()))
            .forEach(fieldInformation -> {
                CollectionField collectionField = fieldInformation.getCollectionField();
                Object obj = null;
                String fieldName = fieldInformation.getName();
                if ((collectionField == null || StringUtils.isBlank(collectionField.value()))
                        && PropertyCache.camelToUnderline){
                    fieldName = StringUtils.camelToUnderline(fieldName);
                }
                if (ignoreType.contains(fieldInformation.getTypeClass())){
                    obj = fieldInformation.getValue();
                }
                if (collectionField != null && collectionField.isObjectId()) {
                    obj = ObjectIdUtil.getObjectIdValue(fieldInformation.getValue());
                }
                Object currentValue = obj == null ? fieldInformation.getValue() : obj;
                for (FieldHandler fieldHandler : FieldHandlerChain.getInstance()) {
                    if (fieldHandler.activate().apply(fieldInformation)) {
                        Object handlerResult = fieldHandler.handler(fieldInformation, currentValue);
                        if (handlerResult != null) {
                            obj = handlerResult;
                            currentValue = handlerResult;
                        }
                    }
                }
                // 如果字段处理器均未返回非null结果，则继续走默认处理
                if (obj != null) {
                    BsonUtil.addToMap(bson, fieldName, obj);
                } else {
                    writeProperties(bson, fieldName, fieldInformation.getValue(),collectionField);
                }
            });
}

private void writeProperties(Bson bson, String key, Object sourceObj, CollectionField collectionField) {
    if (shouldIgnoreNull(sourceObj, collectionField)) {
        return;
    }
    BsonUtil.addToMap(bson, key, writeProperties(sourceObj));
}

private void writeProperties(Bson bson, String key, Object sourceObj) {
    if (shouldIgnoreNull(sourceObj, null)) {
        return;
    }
    BsonUtil.addToMap(bson, key, writeProperties(Holder.isNull(sourceObj)));
}

private boolean shouldIgnoreNull(Object sourceObj, CollectionField collectionField) {
    // 如果 collectionField 不为 null，且有 ignoreNull 属性，则基于该属性做判断
    if (collectionField != null && !collectionField.ignoreNull() && sourceObj == null) {
        return false;
    }
    return PropertyCache.ignoringNull && sourceObj == null;
}

private Object writeProperties(Object sourceObj){
    Object resultObj;
    MappingStrategy<Object> mappingStrategy = null;
    if (sourceObj != null) {
        mappingStrategy = getMappingStrategy(sourceObj.getClass());
    }
    if (mappingStrategy != null) {
        try {
            resultObj = mappingStrategy.mapping(sourceObj);
        } catch (IllegalAccessException e) {
            String error = String.format("Exception mapping %s to simple type", sourceObj.getClass().getName());
            log.error(error,e);
            throw new MongoPlusWriteException(error);
        }
    } else if (sourceObj == null ||
            simpleTypeHolder.isSimpleType(sourceObj.getClass()) ||
            simpleTypeHolder.isMongoType(sourceObj.getClass())) {
        resultObj = getPotentiallyConvertedSimpleWrite(sourceObj);
    } else if (ClassTypeUtil.isTargetClass(Collection.class,sourceObj.getClass()) || sourceObj.getClass().isArray()) {
        resultObj = writeCollectionInternal(BsonUtil.asCollection(sourceObj), new ArrayList<>());
    } else if (ClassTypeUtil.isTargetClass(Map.class,sourceObj.getClass())) {
        resultObj = writeMapInternal((Map<?, ?>) sourceObj,new Document());
    } else {
        resultObj = writeInternal(sourceObj,new Document());
    }
    return resultObj;
}

@Override
public <T> T readInternal(Object sourceObj, TypeReference<T> typeReference){
    Class<?> clazz = typeReference.getClazz();
    ConversionStrategy<?> conversionStrategy = getConversionStrategy(clazz);

    try {
        if (ClassTypeUtil.isTargetClass(Collection.class,clazz)) {
            if (isMultiDimensionalCollection(typeReference)) {
                return handleDefaultType(sourceObj, clazz, conversionStrategy);
            } else {
                return handleCollectionType(sourceObj, typeReference, clazz, conversionStrategy);
            }
        } else if (ClassTypeUtil.isTargetClass(Map.class,clazz)) {
            return handleMapType(sourceObj, typeReference, clazz, conversionStrategy);
        } else {
            return handleDefaultType(sourceObj, clazz, conversionStrategy);
        }
    } catch (IllegalAccessException e) {
        throw new RuntimeException(e);
    }
}

