@Override
public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
    if (log.isDebugEnabled()) log.info("advance proxy hit method: "+ method.getName());
    Invocation invocation = new Invocation(proxy, target, method, args);
    AdvancedFunction function = advancedInterceptor.activate();
    if (function.get(invocation)) {
        return advancedInterceptor.intercept(invocation);
    }
    try {
        return method.invoke(target,args);
    } catch (Throwable e) {
        throw ExceptionUtil.unwrapThrowable(e);
    }
}

@Override
@SuppressWarnings("unchecked")
public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {

    // 参数替换拦截器
    ExecuteMethodEnum executeMethodEnum = ExecuteMethodEnum.getMethod(method.getName());
    MethodExecutorStrategy executor = ExecutorProxyCache.EXECUTOR_MAP.get(executeMethodEnum);
    MongoCollection<Document> collection = (MongoCollection<Document>) args[args.length - 1];
    if (Objects.nonNull(executor)) {
        InterceptorChain.getInterceptors().forEach(interceptor -> {
            interceptor.beforeExecute(executeMethodEnum, args, collection);
            executor.invoke(interceptor, args);
        });
    }

    Object invoke;
    try {
        invoke = method.invoke(target, args);
    } catch (Throwable e) {
        throw ExceptionUtil.unwrapThrowable(e);
    }
    InterceptorChain.getInterceptors().forEach(interceptor -> interceptor.afterExecute(executeMethodEnum,args,invoke, collection));
    return invoke;

}

@SuppressWarnings({"unchecked", "rawtypes"})
public class EnumConversionStrategy<T> implements ConversionStrategy<Enum> {

    /**
     * 缓存每个枚举类的值到枚举实例的映射关系
     *
     */
    private final Map<Class<? extends Enum>, Map<Object, Enum>> enumValueCache = new ConcurrentHashMap<>();

    @Override
    public Enum convertValue(Object fieldValue, Class<?> fieldType, MongoConverter mongoConverter) throws IllegalAccessException {
        Class<? extends Enum> enumType = (Class<? extends Enum>) fieldType;

        // 初始化缓存并获取值到枚举实例的映射
        Map<Object, Enum> valueToEnumMap = enumValueCache.computeIfAbsent(enumType, this::initializeEnumCache);

        if (valueToEnumMap != null) {
            if (valueToEnumMap.containsKey(fieldValue)){
                return valueToEnumMap.get(fieldValue);
            }
        }
        // 如果没有使用注解，或未通过注解标注的字段值找到对应的枚举常量，则先尝试使用valueOf方式，如果失败则抛出异常
        try {
            return Enum.valueOf(enumType, (String) fieldValue);
        } catch (Exception e){
            throw new IllegalArgumentException("No matching enum constant found for value: " + fieldValue);
        }
    }

    /**
     * 初始化枚举类的值到枚举实例的映射关系
     */
    private Map<Object, Enum> initializeEnumCache(Class<? extends Enum> enumType) {
        // 获取标注了 @EnumValue 的字段
        Field[] fields = enumType.getDeclaredFields();
        FieldInformation fieldInformation = null;
        for (Field field : fields) {
            EnumValue enumValue = field.getAnnotation(EnumValue.class);
            if (enumValue != null){
                fieldInformation = new SimpleFieldInformation<>(enumValue, field);
                break;
            }
        }

        if (fieldInformation == null) {
            return null;
        }
        Map<Object, Enum> valueToEnumMap = new ConcurrentHashMap<>();
        for (Enum enumConstant : enumType.getEnumConstants()) {
            Object value = fieldInformation.getValue(enumConstant);
            if (value != null) {
                valueToEnumMap.put(value, enumConstant);
            }
        }
        return valueToEnumMap;
    }
}

@Override
public Object mapping(Enum fieldValue) throws IllegalAccessException {
    FieldInformation fieldInformation = getFieldInformation(fieldValue);
    if (fieldInformation == null) {
        return fieldValue.name();
    }
    EnumValue enumValue = fieldInformation.getAnnotation(EnumValue.class);
    if (enumValue.valueStore()){
        return fieldInformation.getValue(fieldValue);
    }
    return fieldValue.name();
}

public static void autoCreateTimeSeries(Collection<Class<?>> classCollection, MongoPlusClient mongoPlusClient){
    if (CollUtil.isEmpty(classCollection)) {
        return;
    }
    classCollection.forEach(collectionClass -> {
        TimeSeries timeSeries = collectionClass.getAnnotation(TimeSeries.class);
        String dataSource = DataSourceNameCache.getDataSource();
        if (StringUtils.isNotBlank(timeSeries.dataSource())){
            dataSource = timeSeries.dataSource();
        }
        MongoClient mongoClient = mongoPlusClient.getMongoClient(dataSource);
        MongoDatabase mongoDatabase = mongoClient.getDatabase(mongoPlusClient.getDatabase(collectionClass));
        Document paramDocument = new Document();
        paramDocument.put("listCollections",1);
        paramDocument.put("filter",new Document("type","timeseries"));
        Document document = mongoDatabase.runCommand(paramDocument);
        List<String> timeSeriesList = document.get("cursor", Document.class)
                .getList("firstBatch", Document.class)
                .stream().map(doc -> doc.getString("name"))
                .collect(Collectors.toList());
        String collectionName = AnnotationOperate.getCollectionName(collectionClass);
        if (timeSeriesList.contains(collectionName)){
            log.warn("The {} temporal collection already exists",collectionName);
            return;
        }
        TypeInformation typeInformation = TypeInformation.of(collectionClass);
        TimeSeriesOptions options = new TimeSeriesOptions(getFieldNameAndCheck(typeInformation,timeSeries.timeField()));
        options.granularity(timeSeries.granularity());
        if (StringUtils.isNotBlank(timeSeries.metaField())){
            options.metaField(getFieldNameAndCheck(typeInformation,timeSeries.metaField()));
        }
        if (timeSeries.bucketMaxSpan() > 0){
            options.bucketMaxSpan(timeSeries.bucketMaxSpan(), TimeUnit.SECONDS);
            options.metaField(null);
        }
        if (timeSeries.bucketRounding() > 0){
            options.bucketRounding(timeSeries.bucketRounding(), TimeUnit.SECONDS);
            options.metaField(null);
        }
        CreateCollectionOptions createCollectionOptions = new CreateCollectionOptions();
        createCollectionOptions.timeSeriesOptions(options);
        if (timeSeries.expireAfter() > 0){
            createCollectionOptions.expireAfter(timeSeries.expireAfter(), TimeUnit.SECONDS);
        }
        try {
            mongoDatabase.createCollection(
                    collectionName,
                    createCollectionOptions);
        } catch (MongoCommandException ignored){}
    });
}

public static void autoCreateIndexes(Collection<Class<?>> classCollection, MongoPlusClient mongoPlusClient){
    if (CollUtil.isEmpty(classCollection)) {
        return;
    }
    List<IndexMetaObject> indexMetaObjectList = IndexUtil.getIndex(classCollection);
    if (CollUtil.isNotEmpty(indexMetaObjectList)) {
        indexMetaObjectList.forEach(indexMetaObject -> {
            if (CollUtil.isNotEmpty(indexMetaObject.getIndexModels())){
                String dataSource = DataSourceNameCache.getDataSource();
                if (StringUtils.isNotBlank(indexMetaObject.getDataSource())){
                    dataSource = indexMetaObject.getDataSource();
                }
                Class<?> clazz = indexMetaObject.getTypeInformation().getClazz();
                MongoCollection<Document> collection = mongoPlusClient.getCollectionManager(dataSource,clazz)
                        .getCollection(clazz);
                collection.createIndexes(indexMetaObject.getIndexModels());
            }
        });
    }
}

