            sources.add(semanticSource("mongo-plus-core/src/main/java/com/mongoplus/conditions/operation/ConditionOperators.java",
                    "toDate; sum; add; substrBytes", "标记值直接放入 Document 或操作数数组；Lambda 路径使用美元前缀。"));
