public static void commitCurrentAllTransaction(){
    Collection<MongoTransactionStatus> mongoTransactionStatuses =
            getAllMongoTransactionStatus().values();
    mongoTransactionStatuses.forEach(MongoTransactionalManager::commitTransaction);
}

@Override
public void beforeExecute(ExecuteMethodEnum executeMethodEnum, Object[] source,
                          MongoCollection<Document> collection) {
    // 获取所有数据源
    List<String> dataSourceList = new ArrayList<>(DataSourceNameCache.getBasePropertyMap().keySet());

    // 获取分片策略
    List<String> dsNameList = dataSourceShardingHandler.getHandleShardingStrategy(executeMethodEnum);

    DataSourceShardingStrategy shardingStrategy = dataSourceShardingHandler.getDataSourceShardingStrategy();

    String currentDataSourceName = DataSourceNameCache.getDataSource();

    // 根据分片策略决定数据源
    if (shardingStrategy != null) {
        String shardingDsName = shardingStrategy.sharding(currentDataSourceName, executeMethodEnum, source);
        dsNameList = dataSourceShardingHandler.handleDsName(shardingDsName, dataSourceList);
    } else {
        dsNameList = dsNameList.stream()
                .flatMap(dsName -> dataSourceShardingHandler.handleDsName(dsName, dataSourceList).stream())
                .collect(Collectors.toList());
    }

    // 当前数据源
    String dsName = currentDataSourceName;

    if (CollUtil.isEmpty(dsNameList)) {
        log.error("No data source hit");
    } else {
        // 去重并选择负载均衡后的数据源
        dsName = dataSourceShardingHandler.loadBalance(dsNameList.stream().distinct().collect(Collectors.toList()));
    }

    if (log.isTraceEnabled()) {
        log.trace("Hit " + dsName + " DataSource");
    }
    if (StringUtils.isBlank(dsName)) {
        log.error("No data source hit, no data source replacement will be performed, dsName value is " + dsName);
    }
    // 如果命中了新数据源
    if (!Objects.equals(dsName, currentDataSourceName)) {
        // 获取新的 MongoCollection
        MongoNamespace namespace = collection.getNamespace();
        // 获取当前线程持有的事务
        ClientSession currentClientSession = MongoTransactionContext.getClientSessionContext();
        BaseProperty baseProperty = DataSourceNameCache.getBaseProperty(dsName);
        if (StringUtils.isNotBlank(baseProperty.getReplicaSet()) &&
                currentClientSession != null) {
            // 获取MongoClient
            MongoClient mongoClient = mongoPlusClient.getMongoClient(dsName);
            // 根据当前线程持有的事务配置，重新拿到新事务
            ClientSession clientSession = dataSourceShardingHandler.handleTransactional(
                    currentClientSession, mongoClient);
            MongoTransactionalManager.startTransaction(clientSession,clientSession.getTransactionOptions());
        } else if (currentClientSession != null) {
            sessionIsNotNull = true;
        }
        // 拿到新数据源的Collection
        MongoCollection<Document> newCollection = mongoPlusClient.getCollection(
                dsName, namespace.getDatabaseName(), namespace.getCollectionName()
        );

        // 更新源数据
        source[source.length - 1] = newCollection;
    }
}

@Override
public Object transaction(ThrowableSupplier<Object> supplier, MongoTransactional mongoTransactional) throws Throwable {
    ClientSession session = MongoTransactionalManager.getTransaction(mongoTransactional);
    MongoTransactionStatus status = MongoTransactionalManager.getTransactionStatus(session, null);
    MongoTransactionalManager.startTransaction(status);
    String currentDataSource = DataSourceNameCache.getDataSource();
    ShardingTransactionContext.addResourcesTransactionStatus(currentDataSource,status);
    try {
        Object result = supplier.get();
        ShardingTransactionContext.commitCurrentAllTransaction();
        return result;
    } catch (Throwable e) {
        handleTransactionException(mongoTransactional, e);
        throw e;
    } finally {
        ShardingTransactionContext.closeAllSession();
    }
}

public class XPluginAuto implements Plugin {
    @Override
    public void start(AppContext context) {
        //mongo-plus插件配置
        context.beanMake(MongoPlusConfiguration.class);
        context.beanInterceptorAdd(MongoTransactional.class,new MongoTransactionalAspect());
        context.beanMake(MongoDBFieldProperty.class);
        context.beanMake(MongoEncryptorProperty.class);
        context.beanMake(MongoDataSourceAspect.class);
        context.beanMake(TenantAspect.class);
        context.beanMake(MongoLogicIgnoreAspect.class);
        context.beanInjectorAdd(Inject.class,MongoMapper.class,registerMongoMapper());
    }

    BeanInjector<Inject> registerMongoMapper() {
        return (vh,annotation) -> {
            Class<?> mapperInterface = vh.getType();
            Object target = vh.context().getBean(mapperInterface);
            if (target == null && mapperInterface.isInterface()) {
                MetadataReader metadataReader = new MetadataReaderFactory(mapperInterface).getMetadataReader();
                Class<?> mongoMapper = metadataReader.getClassMetadata().getInterface(MongoMapper.class);
                Mongo mongo = metadataReader.getAnnotationMetadata().getAnnotation(Mongo.class);
                if (mongoMapper != null && mongo != null) {
                    vh.context().getBeanAsync(BaseMapper.class,baseMapper -> {
                        Object mongoMapperProxyInstance = MapperProxy.wrap(baseMapper, mapperInterface);
                        vh.context().wrapAndPut(mapperInterface,mongoMapperProxyInstance);
                        vh.setValue(mongoMapperProxyInstance);
                    });
                } else {
                    vh.context().getBeanAsync(mapperInterface,vh::setValue);
                }
            }
        };
    }

}
